output.sparql:
SELECT ?building WHERE {
  ?building wdt:P31 wd:Q4167410 ;
            wdt:P2048 ?height ;
            wdt:P571 ?completion.
  FILTER (str(?completion) < "2019-01-01")
  ORDER BY DESC(?height)
  LIMIT 1
}

# Note: This query should return the Burj Khalifa (wd:Q3631932) as the tallest building completed before 2019, which was the tallest in 2018.

