SELECT ?building ?label WHERE {
  ?building wdt:P31 wd:Q4167410 ;
            wdt:P2048 ?height ;
            wdt:P571 ?completion.
  FILTER (str(?completion) < "2019-01-01")
  OPTIONAL { ?building rdfs:label ?label. FILTER (lang(?label) = "en") }
} ORDER BY DESC(?height) LIMIT 1

